  const aistudio = (window as any).aistudio;
  const keyExists = !!process.env.API_KEY || (aistudio && await aistudio.hasSelectedApiKey());

  return {
    connected: !!keyExists,
    provider: "Antako Secure Vault",
    latency: `${Math.floor(Math.random() * 30) + 10}ms`,
    status: keyExists ? 'ONLINE' : 'OFFLINE'
  };
};

