  drawContainer(doc, margin + (pageWidth - margin * 2) / 2 + 2, cursorY, (pageWidth - margin * 2) / 2 - 2, 30, COLORS.bgLight);
  doc.setFontSize(8);
  doc.setTextColor(...COLORS.slateMed);
  doc.text("TRUST STANDING", margin + (pageWidth - margin * 2) / 2 + 7, cursorY + 8);
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.secondary);
  doc.text(summary.domainAuthorityEstimate, margin + (pageWidth - margin * 2) / 2 + 7, cursorY + 22);

  cursorY += 45;

  // Vision Statement
  doc.setFont("helvetica", "bolditalic");
  doc.setFontSize(12);
  doc.setTextColor(...COLORS.slateDark);
  const visionLines = doc.splitTextToSize(`"${summary.strategicAdvice}"`, pageWidth - margin * 2);
  doc.text(visionLines, margin, cursorY);
  cursorY += (visionLines.length * 6) + 10;

  // Core Pillars
  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.secondary);
  doc.text("Strategic Pillars of Growth", margin, cursorY);
  cursorY += 8;

  summary.strategicPillars.forEach((pillar) => {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(...COLORS.slateDark);
    doc.text(pillar.title, margin + 5, cursorY);
    cursorY += 5;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(...COLORS.slateMed);
    const pLines = doc.splitTextToSize(pillar.description, pageWidth - margin * 2 - 10);
    doc.text(pLines, margin + 5, cursorY);
    cursorY += (pLines.length * 5) + 6;
  });

  // New Page for Roadmap
  doc.addPage();
  cursorY = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.secondary);
  doc.text("Technical Execution Roadmap", margin, cursorY);
  cursorY += 10;

  summary.technicalRoadmap.forEach((step, idx) => {
    drawContainer(doc, margin, cursorY, pageWidth - margin * 2, 10, COLORS.bgLight);
    doc.setFontSize(9);
    doc.setTextColor(...COLORS.slateDark);
    doc.text(`${idx + 1}. ${step}`, margin + 5, cursorY + 6.5);
    cursorY += 14;
  });

  // Content Gap Analysis
  cursorY += 10;
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.secondary);
  doc.text("Semantic Gap Deep-Dive", margin, cursorY);
  cursorY += 8;
  doc.setFontSize(9);
  doc.setFont("helvetica", "italic");
  doc.setTextColor(...COLORS.slateMed);
  const gapLines = doc.splitTextToSize(summary.contentGapAnalysis, pageWidth - margin * 2);
  doc.text(gapLines, margin, cursorY);

  drawFooter(doc, pageWidth, pageHeight, margin);
  doc.save(`master-website-strategy-${new Date().toISOString().slice(0, 10)}.pdf`);
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings, CustomProxy, LogEntry, BulkSummary } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent, generateBulkSummary } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
import { checkBackendHealth, SystemHealth, isGeminiKeySelected } from './services/authService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';
