import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation, BulkSummary, ChatMessage } from "../types";
import { getSecureApiKey } from "./authService";

const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER },
    eeatScore: { type: Type.NUMBER },
    llmOptimizationScore: { type: Type.NUMBER },
    isYMYL: { type: Type.BOOLEAN },
    summary: { type: Type.STRING },
    strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
    weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          priority: { type: Type.STRING },
          action: { type: Type.STRING },
          description: { type: Type.STRING },
          affectedContent: { type: Type.STRING },
          fixSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          expectedImpact: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: { type: Type.ARRAY, items: { type: Type.STRING } },
    lsiKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
    llmEntities: { type: Type.ARRAY, items: { type: Type.STRING } },
    sentiment: { 
      type: Type.OBJECT,
      properties: {
        label: { type: Type.STRING },
        score: { type: Type.NUMBER },
        explanation: { type: Type.STRING }
      },
      required: ['label', 'score', 'explanation']
    }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations', 'lsiKeywords', 'llmEntities', 'sentiment']
};

const bulkSummarySchema = {
  type: Type.OBJECT,
  properties: {
    overallScore: { type: Type.NUMBER },
    domainAuthorityEstimate: { type: Type.STRING },
    coreOpportunities: { type: Type.ARRAY, items: { type: Type.STRING } },
    topCriticalFixes: { type: Type.ARRAY, items: { type: Type.STRING } },
    strategicAdvice: { type: Type.STRING },
    strategicPillars: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ['title', 'description']
      }
    },
    technicalRoadmap: { type: Type.ARRAY, items: { type: Type.STRING } },
    contentGapAnalysis: { type: Type.STRING }
  },
  required: ['overallScore', 'domainAuthorityEstimate', 'coreOpportunities', 'topCriticalFixes', 'strategicAdvice', 'strategicPillars', 'technicalRoadmap', 'contentGapAnalysis']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings,
  chatHistory: ChatMessage[] = []
): Promise<AnalysisResult> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });

    const isPro = model.includes('pro');
    const strictnessMap = { low: 0.5, medium: 0.3, high: 0.1 };

    // Formulate the instruction context from chat history
    const chatContext = chatHistory.length > 0 
      ? `\n\n--- ADDITIONAL USER GUIDANCE FROM CHAT ASSISTANT ---\n${chatHistory.map(m => `${m.role.toUpperCase()}: ${m.parts[0].text}`).join('\n')}`
      : '';

    const prompt = `${adminSettings.promptTemplate}

    URL: ${url}
    TITLE: ${pageTitle}
    CONTENT: ${content.substring(0, 30000)}
    FOCUS: ${criteria.focusArea}
    INSTRUCTIONS: ${criteria.customInstructions}${chatContext}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: strictnessMap[criteria.strictness] || 0.3,
        thinkingConfig: isPro ? { thinkingBudget: 32768 } : undefined
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Model returned empty text response.");

    const parsedData = JSON.parse(resultText);

    // Manual Sort Priority: High > Medium > Low
    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };
    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    }

    return {
      url,
      pageTitle,
      modelUsed: model,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(`Analysis failed: ${error.message}`);
  }
};

export const sendChatToGemini = async (message: string, history: ChatMessage[]): Promise<string> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        thinkingConfig: { thinkingBudget: 32768 },
        systemInstruction: "You are the 'ContentAudit AI Strategy Assistant'. Your goal is to help users refine their content audit strategy, adjust reporting styles, and provide deep insights into SEO, E-E-A-T, and GEO. You have access to deep thinking mode to handle complex requests. Keep responses concise but highly professional and strategic."
      }
    });

    return response.text || "I'm sorry, I couldn't generate a response.";
  } catch (error: any) {
    console.error("Chat API Error:", error);
    throw new Error(`Chat failed: ${error.message}`);
  }
};

export const generateBulkSummary = async (
  results: AnalysisResult[],
  model: ModelType
): Promise<BulkSummary> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });

    const synthesisData = results.map(r => ({
      url: r.url,
      summary: r.summary,
      scores: { seo: r.seoScore, eeat: r.eeatScore, geo: r.llmOptimizationScore },
      weaknesses: r.weaknesses,
      topRecs: r.recommendations.slice(0, 3).map(rec => rec.action),
      entities: r.llmEntities
    }));

    const prompt = `You are a visionary Head of Growth and SEO Strategy. You have just completed a deep audit of a cluster of web pages.
    Your task is to synthesize this data into a comprehensive "Master Website Strategy" that defines the path to dominance in both traditional search and AI-driven generative engines.

    AUDIT DATA:
    ${JSON.stringify(synthesisData, null, 2)}

    Please produce a structured, high-insight strategic report in JSON format following the provided schema.

    Requirements for fields:
    - overallScore: A weighted average performance score (0-100).
    - domainAuthorityEstimate: A qualitative trust level label (e.g., "Fragmented Trust", "Authoritative Leader", "Informational Hub").
    - coreOpportunities: 4-6 specific, high-level tactical opportunities identified from patterns in the data.
    - topCriticalFixes: The 3 most damaging systemic issues that must be solved immediately across the site.
    - strategicAdvice: A visionary 2-3 sentence directive on the core brand shift required.
    - strategicPillars: 3 detailed "Pillars of Growth". Each with a punchy 'title' and a 20-30 word strategic 'description'.
    - technicalRoadmap: 4 sequential steps for technical implementation (e.g., "1. Author entity mapping", "2. Structured data overhaul").
    - contentGapAnalysis: A 50-word deep-dive into the "Missing Semantic Layer" - what specific topics or entities are absent that LLMs expect to see?

    Be extremely professional, critical, and direct. Avoid generic advice. Focus on the actual entities and weaknesses found in the data.`;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: bulkSummarySchema,
        temperature: 0.2
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Synthesis failed.");

    return JSON.parse(resultText);
  } catch (error: any) {
    console.error("Bulk Synthesis Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { AnalysisCriteria, ChatMessage } from '../types';
import CustomSelect from './CustomSelect';
import { sendChatToGemini } from '../services/geminiService';

interface CriteriaSettingsProps {
  criteria: AnalysisCriteria;
  chatHistory: ChatMessage[];
  onCriteriaChange: (newCriteria: AnalysisCriteria) => void;
  onChatHistoryChange: (newHistory: ChatMessage[]) => void;
}

const CriteriaSettings: React.FC<CriteriaSettingsProps> = ({ criteria, chatHistory, onCriteriaChange, onChatHistoryChange }) => {
  const [chatInput, setChatInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const handleCriteriaChange = (field: keyof AnalysisCriteria, value: any) => {
    onCriteriaChange({ ...criteria, [field]: value });
  };

  const handleSendChat = async () => {
    if (!chatInput.trim() || isSending) return;

    const userMsg: ChatMessage = { role: 'user', parts: [{ text: chatInput }] };
    const updatedHistory = [...chatHistory, userMsg];
    onChatHistoryChange(updatedHistory);
    setChatInput('');
    setIsSending(true);

    try {
      const responseText = await sendChatToGemini(chatInput, chatHistory);
      const modelMsg: ChatMessage = { role: 'model', parts: [{ text: responseText }] };
      onChatHistoryChange([...updatedHistory, modelMsg]);
    } catch (err: any) {
      const errorMsg: ChatMessage = { role: 'model', parts: [{ text: `Error: ${err.message}` }] };
      onChatHistoryChange([...updatedHistory, errorMsg]);
    } finally {
      setIsSending(false);
    }
  };

  const strictnessOptions = [
    { value: 'low', label: 'Low (Baseline Check)' },
    { value: 'medium', label: 'Medium (Standard)' },
    { value: 'high', label: 'High (Strict Audit)' },
  ];

  const focusAreaOptions = [
    { value: 'General SEO', label: 'General SEO' },
    { value: 'Medical/Health', label: 'Medical & Health (YMYL)' },
    { value: 'Finance', label: 'Finance & Crypto (YMYL)' },
    { value: 'E-commerce', label: 'E-commerce' },
    { value: 'Blog/News', label: 'Editorial & News' },
    { value: 'Technical Documentation', label: 'Technical Docs' },
  ];

  return (
    <div className="bg-white p-6 rounded-2xl shadow-xl shadow-slate-200/50 border border-white space-y-6 flex flex-col h-full min-h-[500px]">
      <div className="space-y-6">
        <h3 className="text-sm font-bold text-slate-900 flex items-center gap-2 uppercase tracking-wide">
          <span className="w-1.5 h-4 bg-blue-500 rounded-full"></span>
          Audit Configuration
        </h3>

        <div className="space-y-4">
          <div>
            <CustomSelect
              label="Strictness Level"
              value={criteria.strictness}
              onChange={(val) => handleCriteriaChange('strictness', val)}
              options={strictnessOptions}
            />
          </div>

          <div>
            <CustomSelect
              label="Focus Area"
              value={criteria.focusArea}
              onChange={(val) => handleCriteriaChange('focusArea', val)}
              options={focusAreaOptions}
            />
          </div>
        </div>
      </div>

      <div className="flex-grow flex flex-col pt-4 border-t border-slate-50 overflow-hidden">
        <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          Strategy Assistant (PRO)
        </h3>

        <div className="flex-grow overflow-y-auto bg-slate-50/50 rounded-xl p-4 mb-4 space-y-4 border border-slate-100 scrollbar-thin scrollbar-thumb-slate-200">
          {chatHistory.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-40 px-4">
                <svg className="w-8 h-8 mb-2 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                <p className="text-[10px] font-bold uppercase tracking-widest">Adjust research strategy & reporting style via chat.</p>
            </div>
          ) : (
            chatHistory.map((msg, i) => (
              <div key={i} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`max-w-[85%] px-3 py-2 rounded-2xl text-xs leading-relaxed shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-blue-600 text-white rounded-tr-none' 
                    : 'bg-white text-slate-700 border border-slate-100 rounded-tl-none'
                }`}>
                  {msg.parts[0].text}
                </div>
              </div>
            ))
          )}
          {isSending && (
            <div className="flex flex-col items-start animate-pulse">
                <div className="bg-slate-100 px-3 py-2 rounded-2xl rounded-tl-none text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce"></span>
                    Assistant is thinking...
                </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="relative">
          <textarea
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSendChat();
              }
            }}
            placeholder="E.g., 'Make the report more aggressive on E-E-A-T faults'..."
            className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-4 pr-12 py-3 text-sm text-slate-900 h-20 focus:ring-2 focus:ring-blue-100 focus:border-blue-500 outline-none resize-none transition-all placeholder-slate-400 shadow-sm"
          />
          <button 
            onClick={handleSendChat}
            disabled={!chatInput.trim() || isSending}
            className="absolute bottom-3 right-3 p-2 bg-blue-600 text-white rounded-lg shadow-lg hover:bg-blue-700 transition-all active:scale-90 disabled:opacity-50 disabled:scale-100"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

