export const analyzeContent = async (
  url: string,
  pageTitle: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings,
  chatHistory: ChatMessage[] = []
): Promise<AnalysisResult> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });

    const isPro = model.includes('pro');
    const strictnessMap = { low: 0.5, medium: 0.3, high: 0.1 };
    const langLabel = criteria.language === 'ua' ? 'Ukrainian' : 'English';

    const chatContext = chatHistory.length > 0 
      ? `\n\n--- ADDITIONAL USER GUIDANCE FROM CHAT ASSISTANT ---\n${chatHistory.map(m => `${m.role.toUpperCase()}: ${m.parts[0].text}`).join('\n')}`
      : '';

    const prompt = `${adminSettings.promptTemplate}

    URL: ${url}
    TITLE: ${pageTitle}
    CONTENT: ${content.substring(0, 30000)}
    FOCUS: ${criteria.focusArea}
    INSTRUCTIONS: ${criteria.customInstructions}

    MANDATORY LANGUAGE REQUIREMENT: You MUST generate the entire analysis and all text values in the JSON in ${langLabel}.
    ${chatContext}`;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: strictnessMap[criteria.strictness] || 0.3,
        thinkingConfig: isPro ? { thinkingBudget: 32768 } : undefined
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Model returned empty text response.");

    const parsedData = JSON.parse(resultText);

    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };
    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => 
        (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      );
    }

    return {
      url,
      pageTitle,
      modelUsed: model,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(`Analysis failed: ${error.message}`);
  }
};

export const sendChatToGemini = async (message: string, history: ChatMessage[], language: 'en' | 'ua'): Promise<string> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });
    const langLabel = language === 'ua' ? 'Ukrainian' : 'English';

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        thinkingConfig: { thinkingBudget: 32768 },
        systemInstruction: `You are the 'ContentAudit AI Strategy Assistant'. Your goal is to help users refine their content audit strategy.
        MANDATORY: You must respond in ${langLabel}. Use professional and strategic tone.`
      }
    });

    return response.text || "No response generated.";
  } catch (error: any) {
    console.error("Chat API Error:", error);
    throw new Error(`Chat failed: ${error.message}`);
  }
};

export const generateBulkSummary = async (
  results: AnalysisResult[],
  model: ModelType,
  language: 'en' | 'ua'
): Promise<BulkSummary> => {
  try {
    const apiKey = await getSecureApiKey();
    const ai = new GoogleGenAI({ apiKey });
    const langLabel = language === 'ua' ? 'Ukrainian' : 'English';

    const synthesisData = results.map(r => ({
      url: r.url,
      summary: r.summary,
      scores: { seo: r.seoScore, eeat: r.eeatScore, geo: r.llmOptimizationScore },
      weaknesses: r.weaknesses,
      topRecs: r.recommendations.slice(0, 3).map(rec => rec.action),
      entities: r.llmEntities
    }));

    const prompt = `You are a visionary Head of Growth and SEO Strategy. Synthesize this cluster audit into a "Master Website Strategy".

    AUDIT DATA:
    ${JSON.stringify(synthesisData, null, 2)}

    MANDATORY LANGUAGE REQUIREMENT: You MUST generate the entire report in ${langLabel}.

    JSON Structure Requirements:
    - overallScore: Weighted average.
    - domainAuthorityEstimate: Qualitative trust level.
    - coreOpportunities: 4-6 high-level tactical opportunities.
    - topCriticalFixes: 3 systemic issues.
    - strategicAdvice: 2-3 sentence directive.
    - strategicPillars: 3 detailed pillars with 'title' and 'description'.
    - technicalRoadmap: 4 implementation steps.
    - contentGapAnalysis: 50-word deep-dive into semantic missing layers.`;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: bulkSummarySchema,
        temperature: 0.2
      }
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Synthesis failed.");

    return JSON.parse(resultText);
  } catch (error: any) {
    console.error("Bulk Synthesis Error:", error);
    throw error;
  }
};

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult, BulkSummary } from "../types";

// --- Color Palette (Modern & Minimal) ---
const COLORS = {
  primary: [59, 130, 246] as [number, number, number],    // Blue 500
  secondary: [99, 102, 241] as [number, number, number],  // Indigo 500
  slateDark: [30, 41, 59] as [number, number, number],    // Slate 800
  slateMed: [71, 85, 105] as [number, number, number],    // Slate 600
  slateLight: [148, 163, 184] as [number, number, number],// Slate 400
  bgLight: [248, 250, 252] as [number, number, number],   // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],

  // Status Colors
  success: [16, 185, 129] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
};

const drawFooter = (doc: jsPDF, pageWidth: number, pageHeight: number, margin: number) => {
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateLight);

      doc.textWithLink("// work in progress for fixes & suggestions contact Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });
      doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
  }
};

const drawContainer = (doc: jsPDF, x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
   doc.setFillColor(...color);
   doc.setDrawColor(...COLORS.border);
   doc.roundedRect(x, y, w, h, 3, 3, 'FD');
};

export const generatePdfReport = (result: AnalysisResult) => {
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 14;
  let cursorY = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 8);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 8, { align: 'right' });

  cursorY += 15;
  doc.setDrawColor(...COLORS.border);
  doc.setLineWidth(0.1);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 6;

  doc.setFontSize(9);
  doc.setTextColor(...COLORS.slateLight);
  doc.text("TARGET URL", margin, cursorY + 3);
  doc.setFontSize(11);
  doc.setTextColor(...COLORS.primary);
  doc.text(result.url, margin + 25, cursorY + 3);

  cursorY += 10;

  const blockGap = 5;
  const blockW = (pageWidth - (margin * 2) - (blockGap * 2)) / 3;
  const blockH = 25;

  const drawStat = (label: string, score: number, x: number) => {
      drawContainer(doc, x, cursorY, blockW, blockH, COLORS.bgLight);
      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateMed);
      doc.setFont("helvetica", "bold");
      doc.text(label.toUpperCase(), x + 6, cursorY + 7);
      doc.setFontSize(18);
      let sc = COLORS.success;
      if (score < 50) sc = COLORS.danger;
      else if (score < 80) sc = COLORS.warning;
      doc.setTextColor(...sc);
      doc.text(`${score}`, x + 6, cursorY + 18);
      doc.setFontSize(10);
      doc.setTextColor(...COLORS.slateLight);
      doc.text("/ 100", x + 16 + (score > 9 ? 10 : 5), cursorY + 18);
      doc.setFillColor(...sc);
      doc.rect(x + 6, cursorY + 21, (blockW - 12) * (score / 100), 1.5, 'F');
  };

  drawStat("SEO Health", result.seoScore, margin);
  drawStat("E-E-A-T Score", result.eeatScore, margin + blockW + blockGap);
  drawStat("AI Readiness", result.llmOptimizationScore, margin + (blockW + blockGap) * 2);

  cursorY += blockH + 10;

  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [['EXECUTIVE SUMMARY']],
      body: [[result.summary]],
      theme: 'plain',
      headStyles: { fillColor: COLORS.white, textColor: COLORS.secondary, fontSize: 11, fontStyle: 'bold', cellPadding: { top: 0, bottom: 2, left: 0 } },
      bodyStyles: { textColor: COLORS.slateMed, fontSize: 10, cellPadding: 0, lineHeight: 1.4 },
      columnStyles: { 0: { cellWidth: 'auto' } }
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;
  const halfPage = (pageWidth - (margin * 2)) / 2;
  const strengthsBody = result.strengths.map(s => [`• ${s}`]);
  const weaknessesBody = result.weaknesses.map(w => [`• ${w}`]);

  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin },
      tableWidth: halfPage - 4,
      head: [['KEY STRENGTHS']],
      body: strengthsBody,
      theme: 'plain',
      headStyles: { textColor: COLORS.success, fontSize: 10, fontStyle: 'bold', cellPadding: { bottom: 3, left: 0 } },
      bodyStyles: { textColor: COLORS.slateDark, fontSize: 9, cellPadding: { top: 1, bottom: 1, left: 2 }, overflow: 'linebreak' }
  });

  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin + halfPage + 4 },
      tableWidth: halfPage - 4,
      head: [['CRITICAL ISSUES']],
      body: weaknessesBody,
      theme: 'plain',
      headStyles: { textColor: COLORS.danger, fontSize: 10, fontStyle: 'bold', cellPadding: { bottom: 3, left: 0 } },
      bodyStyles: { textColor: COLORS.slateDark, fontSize: 9, cellPadding: { top: 1, bottom: 1, left: 2 }, overflow: 'linebreak' }
  });

  doc.addPage();
  cursorY = margin;
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Sentiment & Semantic Profile", margin, cursorY + 6);
  cursorY += 15;
  const sentimentLabel = `${result.sentiment.label} (${result.sentiment.score}/100)`;
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [[`SENTIMENT: ${sentimentLabel}`]],
      body: [[result.sentiment.explanation]],
      theme: 'grid',
      headStyles: { fillColor: result.sentiment.score > 60 ? COLORS.success : result.sentiment.score < 40 ? COLORS.danger : COLORS.warning, textColor: COLORS.white, fontSize: 10, fontStyle: 'bold' },
      bodyStyles: { textColor: COLORS.slateMed, fontSize: 9, cellPadding: 4, fontStyle: 'italic' }
  });
  cursorY = (doc as any).lastAutoTable.finalY + 10;
  const maxLen = Math.max(result.keywordGaps.length, result.lsiKeywords.length, result.llmEntities.length);
  const keywordRows = [];
  for(let i = 0; i < maxLen; i++) { keywordRows.push([result.keywordGaps[i] || '', result.lsiKeywords[i] || '', result.llmEntities[i] || '']); }
  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['KEYWORD GAPS', 'LSI OPPORTUNITIES', 'LLM ENTITIES']],
      body: keywordRows,
      theme: 'grid',
      headStyles: { fillColor: COLORS.bgLight, textColor: COLORS.slateDark, fontStyle: 'bold', lineWidth: 0.1, lineColor: COLORS.border },
      styles: { fontSize: 8, cellPadding: 2, textColor: COLORS.slateMed }
  });

  doc.addPage();
  cursorY = margin;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Optimization Action Plan", margin, cursorY + 6);
  cursorY += 15;
  const planBody = result.recommendations.map(rec => [rec.priority.toUpperCase(), rec.category, rec.action, `${rec.description}\n\nFIX:\n${rec.fixSteps.map(s => `- ${s}`).join('\n')}`, rec.expectedImpact]);
  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['PRIORITY', 'AREA', 'ACTION', 'DETAILS & INSTRUCTIONS', 'IMPACT']],
      body: planBody,
      theme: 'grid',
      styles: { font: 'helvetica', fontSize: 9, lineColor: COLORS.border, lineWidth: 0.1, cellPadding: 4, textColor: COLORS.slateMed, valign: 'top', overflow: 'linebreak' },
      headStyles: { fillColor: COLORS.bgLight, textColor: COLORS.slateDark, fontStyle: 'bold', lineWidth: 0.1, lineColor: COLORS.border, halign: 'left' },
      columnStyles: { 0: { cellWidth: 30, halign: 'center', fontStyle: 'bold' }, 1: { cellWidth: 25 }, 2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary }, 3: { cellWidth: 'auto' }, 4: { cellWidth: 40, fontSize: 8 } },
      didParseCell: (data: any) => {
          if (data.section === 'body' && data.column.index === 0) {
              const p = data.cell.raw;
              if (p === 'HIGH') data.cell.styles.textColor = COLORS.danger;
              else if (p === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
              else data.cell.styles.textColor = COLORS.success;
          }
      }
  });

  drawFooter(doc, pageWidth, pageHeight, margin);
  const now = new Date();
  const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
  const timeStr = now.toISOString().slice(11, 16).replace(/:/g, '');
  let hostname = 'domain';
  try { hostname = new URL(result.url).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) {}
  const cleanHostname = hostname.replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  doc.save(`${cleanHostname}-audit-${dateStr}-${timeStr}.pdf`);
};

export const generateBulkPdfReport = (summary: BulkSummary, urls: string[]) => {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 14;
  let cursorY = margin;

