  doc.setFillColor(...COLORS.slateDark);
  doc.rect(0, 0, pageWidth, 55, 'F');

  doc.setFont("helvetica", "bold");
  doc.setFontSize(22);
  doc.setTextColor(...COLORS.white);
  doc.text("Master Website Strategy", margin, 25);

  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(180, 190, 210);
  doc.text(`Strategic Content Intelligence Report // ${urls.length} Nodes Processed`, margin, 34);
  doc.text(`Generated on ${new Date().toLocaleDateString()}`, margin, 40);

  cursorY = 65;

  // High Level KPIs
  const kpiW = (pageWidth - margin * 2) / 2 - 2;
  const kpiH = 28;

  // KPI 1: Performance
