  // KPI 2: Trust
  drawContainer(doc, margin + kpiW + 4, cursorY, kpiW, kpiH, COLORS.bgLight);
  doc.setFontSize(8);
  doc.setTextColor(...COLORS.slateMed);
  doc.text("DOMAIN TRUST STANDING", margin + kpiW + 9, cursorY + 8);
  doc.setFontSize(13);
