  // Strategic Vision (Advice) - Robust Wrapping
  doc.setFont("helvetica", "bolditalic");
  doc.setFontSize(11);
  doc.setTextColor(...COLORS.slateDark);
  const adviceLines = doc.splitTextToSize(`"${summary.strategicAdvice}"`, pageWidth - margin * 2);
  doc.text(adviceLines, margin, cursorY);
  cursorY += (adviceLines.length * 5.5) + 12;

  // Strategic Pillars Table (Fixes overflow and alignment)
  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['CORE STRATEGIC PILLARS', 'IMPLEMENTATION FOCUS']],
      body: summary.strategicPillars.map(p => [p.title.toUpperCase(), p.description]),
