import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult, BulkSummary } from "../types";

// --- Color Palette (Synchronized with UI) ---
const COLORS = {
  primary: [59, 130, 246] as [number, number, number],    // Blue 500
  secondary: [99, 102, 241] as [number, number, number],  // Indigo 500
  slateDark: [15, 23, 42] as [number, number, number],    // Slate 900
  slateMed: [71, 85, 105] as [number, number, number],    // Slate 600
  slateLight: [148, 163, 184] as [number, number, number],// Slate 400
  bgLight: [248, 250, 252] as [number, number, number],   // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],
  success: [16, 185, 129] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
};

/**
 * Utility to load a Cyrillic-supporting font into jsPDF.
 * We use a CDN-hosted font and add it to the Virtual File System.
 */
const ensureCyrillicFont = async (doc: jsPDF) => {
  try {
    // Check if font already exists to avoid re-loading
    if (doc.getFontList().hasOwnProperty('NotoSans')) return;

    // Fetch NotoSans (supports Cyrillic)
    const fontUrl = 'https://cdn.jsdelivr.net/font-noto/1.0.0/NotoSans-Regular.ttf';
    const response = await fetch(fontUrl);
    const buffer = await response.arrayBuffer();

    // Convert to base64 safely
    let binary = '';
    const bytes = new Uint8Array(buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    const base64 = btoa(binary);

    doc.addFileToVFS('NotoSans-Regular.ttf', base64);
    doc.addFont('NotoSans-Regular.ttf', 'NotoSans', 'normal');
    doc.setFont('NotoSans');
  } catch (e) {
    console.error("Failed to load Cyrillic font, falling back to Helvetica (may result in ? characters for UA)", e);
    doc.setFont('helvetica');
  }
};

const drawFooter = (doc: jsPDF, pageWidth: number, pageHeight: number, margin: number) => {
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(...COLORS.slateLight);
    doc.textWithLink("// work in progress for fixes & suggestions contact Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });
    doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
  }
};

const drawContainer = (doc: jsPDF, x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
  doc.setFillColor(...color);
  doc.setDrawColor(...COLORS.border);
  doc.roundedRect(x, y, w, h, 3, 3, 'FD');
};

export const generatePdfReport = async (result: AnalysisResult) => {
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  await ensureCyrillicFont(doc);

  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 14;
  let cursorY = margin;

  // Header
  doc.setFontSize(24);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 8);
  doc.setFontSize(10);
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 8, { align: 'right' });

  cursorY += 15;
  doc.setDrawColor(...COLORS.border);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 8;

  doc.setFontSize(11);
  doc.setTextColor(...COLORS.primary);
  doc.text(`Target: ${result.url}`, margin, cursorY);
  cursorY += 8;

  // Dashboard Scores
  const blockW = (pageWidth - (margin * 2) - 10) / 3;
  const blockH = 22;

  const drawScore = (label: string, score: number, x: number) => {
    drawContainer(doc, x, cursorY, blockW, blockH, COLORS.bgLight);
    doc.setFontSize(8);
    doc.setTextColor(...COLORS.slateMed);
    doc.text(label.toUpperCase(), x + 6, cursorY + 7);
    doc.setFontSize(18);
    const scoreColor = score > 80 ? COLORS.success : score > 50 ? COLORS.warning : COLORS.danger;
    doc.setTextColor(...scoreColor);
    doc.text(`${score}/100`, x + 6, cursorY + 16);
  };

  drawScore("SEO Health", result.seoScore, margin);
  drawScore("E-E-A-T Score", result.eeatScore, margin + blockW + 5);
  drawScore("GEO Readiness", result.llmOptimizationScore, margin + (blockW + 5) * 2);

  cursorY += blockH + 10;

  // Summary (AutoTable for wrap safety)
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['EXECUTIVE SUMMARY']],
    body: [[result.summary]],
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 10, textColor: COLORS.slateMed, lineHeight: 1.4 },
    headStyles: { font: 'NotoSans', textColor: COLORS.secondary, fontSize: 11, fontStyle: 'bold', cellPadding: { bottom: 2 } },
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // Strengths & Weaknesses
  const halfW = (pageWidth - margin * 2 - 10) / 2;
  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin },
    tableWidth: halfW,
    head: [['STRENGTHS']],
    body: result.strengths.map(s => [`• ${s}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 1 },
    headStyles: { font: 'NotoSans', textColor: COLORS.success, fontStyle: 'bold' }
  });

  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin + halfW + 10 },
    tableWidth: halfW,
    head: [['CRITICAL ISSUES']],
    body: result.weaknesses.map(w => [`• ${w}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 1 },
    headStyles: { font: 'NotoSans', textColor: COLORS.danger, fontStyle: 'bold' }
  });

  doc.addPage();
  cursorY = margin;

  // Recommendations Table
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['PRIORITY', 'ACTION', 'DESCRIPTION & STEPS', 'EXPECTED IMPACT']],
    body: result.recommendations.map(r => [
      r.priority.toUpperCase(),
      r.action,
      `${r.description}\n\nSteps:\n${r.fixSteps.join('\n')}`,
      r.expectedImpact
    ]),
    theme: 'grid',
    styles: { font: 'NotoSans', fontSize: 8, cellPadding: 4, valign: 'top', overflow: 'linebreak' },
    headStyles: { fillColor: COLORS.slateDark, textColor: COLORS.white, fontStyle: 'bold' },
    columnStyles: { 
      0: { cellWidth: 20, halign: 'center' }, 
      1: { cellWidth: 40, fontStyle: 'bold', textColor: COLORS.primary },
      3: { cellWidth: 35 }
    },
    didParseCell: (data: any) => {
      if (data.section === 'body' && data.column.index === 0) {
        if (data.cell.raw === 'HIGH') data.cell.styles.textColor = COLORS.danger;
        else if (data.cell.raw === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
      }
    }
  });

  drawFooter(doc, pageWidth, pageHeight, margin);
  doc.save(`audit-${new Date().getTime()}.pdf`);
};

export const generateBulkPdfReport = async (summary: BulkSummary, urls: string[]) => {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  await ensureCyrillicFont(doc);

  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 14;
  let cursorY = margin;

  // Professional Banner Header
  doc.setFillColor(...COLORS.slateDark);
  doc.rect(0, 0, pageWidth, 50, 'F');
  doc.setFontSize(22);
  doc.setTextColor(...COLORS.white);
  doc.text("Master Website Strategy", margin, 25);
  doc.setFontSize(9);
  doc.setTextColor(180, 190, 210);
  doc.text(`Nodes Audited: ${urls.length} // Intelligence: Gemini 3 Pro`, margin, 34);
  doc.text(`Report Date: ${new Date().toLocaleDateString()}`, margin, 40);

  cursorY = 60;

  // Executive Dashboard Row
  const kpiW = (pageWidth - margin * 2 - 4) / 2;
  drawContainer(doc, margin, cursorY, kpiW, 25, COLORS.bgLight);
  doc.setFontSize(8);
  doc.setTextColor(...COLORS.slateMed);
  doc.text("OVERALL PERFORMANCE INDEX", margin + 5, cursorY + 7);
  doc.setFontSize(18);
  doc.setTextColor(...COLORS.primary);
  doc.text(`${summary.overallScore}/100`, margin + 5, cursorY + 18);

  drawContainer(doc, margin + kpiW + 4, cursorY, kpiW, 25, COLORS.bgLight);
  doc.setFontSize(8);
  doc.setTextColor(...COLORS.slateMed);
  doc.text("ESTIMATED DOMAIN AUTHORITY", margin + kpiW + 9, cursorY + 7);
  doc.setFontSize(14);
  doc.setTextColor(...COLORS.secondary);
  doc.text(summary.domainAuthorityEstimate, margin + kpiW + 9, cursorY + 18);

  cursorY += 35;

  // Vision Statement (AutoTable for perfect text wrapping and no word transitions)
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['STRATEGIC VISION']],
    body: [[`"${summary.strategicAdvice}"`]],
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 11, fontStyle: 'bolditalic', textColor: COLORS.slateDark, cellPadding: { bottom: 8 } },
    headStyles: { font: 'NotoSans', textColor: COLORS.secondary, fontSize: 10, fontStyle: 'bold' }
  });

  cursorY = (doc as any).lastAutoTable.finalY + 2;

  // Strategic Pillars (Using AutoTable to handle multi-line descriptions cleanly)
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['CORE PILLARS', 'IMPLEMENTATION STRATEGY']],
    body: summary.strategicPillars.map(p => [p.title.toUpperCase(), p.description]),
    theme: 'grid',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 5, valign: 'middle', overflow: 'linebreak' },
    headStyles: { fillColor: COLORS.secondary, textColor: COLORS.white, fontStyle: 'bold' },
    columnStyles: { 0: { cellWidth: 50, fontStyle: 'bold', fillColor: [245, 247, 255] } }
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // Technical Growth Roadmap
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['TECHNICAL EXECUTION ROADMAP']],
    body: summary.technicalRoadmap.map((step, i) => [`${i + 1}. ${step}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 2, textColor: COLORS.slateMed },
    headStyles: { font: 'NotoSans', textColor: COLORS.primary, fontSize: 11, fontStyle: 'bold' }
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // Semantic Gap Deep-Dive & Systemic Issues
  const col1W = (pageWidth - margin * 2 - 10) * 0.45;
  const col2W = (pageWidth - margin * 2 - 10) * 0.55;

  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin },
    tableWidth: col1W,
    head: [['SEMANTIC GAP ANALYSIS']],
    body: [[summary.contentGapAnalysis]],
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 8.5, textColor: COLORS.slateMed, fontStyle: 'italic', lineHeight: 1.3 },
    headStyles: { font: 'NotoSans', textColor: COLORS.slateDark, fontStyle: 'bold' }
  });

  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin + col1W + 10 },
    tableWidth: col2W,
    head: [['SYSTEMIC VULNERABILITIES']],
    body: summary.topCriticalFixes.map(fix => [`! ${fix}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 8.5, textColor: COLORS.slateDark },
    headStyles: { font: 'NotoSans', textColor: COLORS.danger, fontStyle: 'bold' }
  });

  drawFooter(doc, pageWidth, pageHeight, margin);
  doc.save(`master-strategy-${new Date().toISOString().slice(0, 10)}.pdf`);
};

