  success: [16, 185, 129] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
};

/**
 * Utility to convert Blob to Base64 safely in browser
 */
const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

/**
 * Ensures Cyrillic support by loading NotoSans font.
 */
const ensureCyrillicFont = async (doc: jsPDF) => {
  try {
    // Check if already added
    const fontExists = doc.getFontList().hasOwnProperty('NotoSans');
    if (fontExists) {
        doc.setFont('NotoSans');
        return;
    }

    // NotoSans Regular with Cyrillic support
    const fontUrl = 'https://cdn.jsdelivr.net/gh/googlefonts/noto-fonts@master/hinted/ttf/NotoSans/NotoSans-Regular.ttf';
    const response = await fetch(fontUrl);
    if (!response.ok) throw new Error("Font fetch failed");

    const blob = await response.blob();
    const base64 = await blobToBase64(blob);

    doc.addFileToVFS('NotoSans-Regular.ttf', base64);
    doc.addFont('NotoSans-Regular.ttf', 'NotoSans', 'normal');
    doc.setFont('NotoSans');
  } catch (e) {
    console.error("Critical: Font loading failed. UA characters may not render.", e);
    // Fallback to standard
    doc.setFont('helvetica');
  }
};

const drawFooter = (doc: jsPDF, pageWidth: number, pageHeight: number, margin: number) => {
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(...COLORS.slateLight);
    doc.textWithLink("// content audit intelligence by Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });
    doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
  }
};

const drawContainer = (doc: jsPDF, x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
  doc.setFillColor(...color);
  doc.setDrawColor(...COLORS.border);
  doc.roundedRect(x, y, w, h, 3, 3, 'FD');
};

export const generatePdfReport = async (result: AnalysisResult) => {
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  await ensureCyrillicFont(doc);

  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 14;
  let cursorY = margin;

  // Header Section
  doc.setFontSize(22);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 6);
  doc.setFontSize(9);
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 6, { align: 'right' });

  cursorY += 12;
  doc.setDrawColor(...COLORS.border);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 8;

  doc.setFontSize(10);
  doc.setTextColor(...COLORS.primary);
  doc.text(`Node: ${result.url}`, margin, cursorY);
  cursorY += 10;

  // Dashboard Scores
  const blockW = (pageWidth - (margin * 2) - 10) / 3;
  const blockH = 24;

  const drawScore = (label: string, score: number, x: number) => {
    drawContainer(doc, x, cursorY, blockW, blockH, COLORS.bgLight);
    doc.setFontSize(7);
    doc.setTextColor(...COLORS.slateMed);
    doc.text(label.toUpperCase(), x + 5, cursorY + 7);
    doc.setFontSize(16);
    const color = score > 80 ? COLORS.success : score > 50 ? COLORS.warning : COLORS.danger;
    doc.setTextColor(...color);
    doc.text(`${score}/100`, x + 5, cursorY + 17);
  };

  drawScore("SEO Health", result.seoScore, margin);
  drawScore("E-E-A-T Quality", result.eeatScore, margin + blockW + 5);
  drawScore("GEO Readiness", result.llmOptimizationScore, margin + (blockW + 5) * 2);

  cursorY += blockH + 10;

  // Analysis Summary
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['STRATEGIC OVERVIEW']],
    body: [[result.summary]],
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 10, textColor: COLORS.slateMed, lineHeight: 1.4, overflow: 'linebreak' },
    headStyles: { font: 'NotoSans', textColor: COLORS.secondary, fontSize: 11, fontStyle: 'bold', cellPadding: { bottom: 3 } },
  });

  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // Strengths & Weaknesses side by side
  const colW = (pageWidth - margin * 2 - 10) / 2;
  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin },
    tableWidth: colW,
    head: [['STRENGTHS']],
    body: result.strengths.map(s => [`• ${s}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 1, textColor: COLORS.slateDark },
    headStyles: { font: 'NotoSans', textColor: COLORS.success, fontStyle: 'bold' }
  });

  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin + colW + 10 },
    tableWidth: colW,
    head: [['CRITICAL ISSUES']],
    body: result.weaknesses.map(w => [`• ${w}`]),
    theme: 'plain',
    styles: { font: 'NotoSans', fontSize: 9, cellPadding: 1, textColor: COLORS.slateDark },
    headStyles: { font: 'NotoSans', textColor: COLORS.danger, fontStyle: 'bold' }
  });

  // Recommendations on a new page
  doc.addPage();
  cursorY = margin;

  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['PRIORITY', 'AREA', 'REQUIRED ACTION', 'IMPLEMENTATION DETAILS', 'EXPECTED IMPACT']],
    body: result.recommendations.map(r => [
      r.priority.toUpperCase(),
      r.category,
      r.action,
      `${r.description}\n\nFIX STEPS:\n${r.fixSteps.map((s,i) => `${i+1}. ${s}`).join('\n')}`,
      r.expectedImpact
    ]),
    theme: 'grid',
    styles: { font: 'NotoSans', fontSize: 8, cellPadding: 4, valign: 'top', overflow: 'linebreak', lineColor: COLORS.border, lineWidth: 0.1 },
    headStyles: { font: 'NotoSans', fillColor: COLORS.slateDark, textColor: COLORS.white, fontStyle: 'bold', halign: 'center' },
    columnStyles: { 
      0: { cellWidth: 20, halign: 'center', fontStyle: 'bold' }, 
      1: { cellWidth: 20 },
      2: { cellWidth: 40, fontStyle: 'bold', textColor: COLORS.primary },
      4: { cellWidth: 35 }
    },
    didParseCell: (data: any) => {
      if (data.section === 'body' && data.column.index === 0) {
        if (data.cell.raw === 'HIGH') data.cell.styles.textColor = COLORS.danger;
        else if (data.cell.raw === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
      }
    }
  });

  drawFooter(doc, pageWidth, pageHeight, margin);
  doc.save(`audit-report-${Date.now()}.pdf`);
};

