                 </div>
                 <button 
                   type="submit"
                   disabled={manualKey.length < 20}
                   className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-200 transition-all disabled:opacity-50 disabled:shadow-none"
                 >
                   Save & Continue
                 </button>
                 {!isAiStudioAvailable && (
                    <p className="text-center text-[10px] text-slate-400">
                      Your key is stored locally in your browser and sent only to Google's API.
                    </p>
                 )}
