            )}

            {!showManual && !isAiStudioAvailable && (
               <button onClick={() => setShowManual(true)} className="text-xs text-blue-600 font-bold hover:underline w-full text-center">
                  I have a key, let me paste it
               </button>
            )}

            {showManual && isAiStudioAvailable && (
               <button onClick={() => setShowManual(false)} className="text-xs text-slate-400 font-bold hover:text-slate-600 w-full text-center">
                  Cancel Manual Entry
               </button>
            )}
          </div>

          <div className="pt-4 border-t border-slate-50">
             <a 
              href="https://ai.google.dev/gemini-api/docs/billing" 
              target="_blank" 
