const ScoreBadge: React.FC<{ label: string; score: number }> = ({ label, score }) => {
  const color = score > 80 ? 'text-emerald-500' : score > 50 ? 'text-amber-500' : 'text-rose-500';
  const bg = score > 80 ? 'bg-emerald-50' : score > 50 ? 'bg-amber-50' : 'bg-rose-50';

  return (
    <div className={`px-4 py-3 rounded-2xl ${bg} flex flex-col items-center justify-center min-w-[100px] border border-white shadow-sm transition-transform hover:scale-105 duration-300`}>
      <span className={`text-2xl font-bold ${color}`}>{score}</span>
      <span className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">{label}</span>
    </div>
  );
};

const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
