export default ResultCard;

/**
 * Auth Service / Secure Vault
 * Simulates a backend point for credential management.
 */

export interface SystemHealth {
  connected: boolean;
  provider: string;
  latency: string;
  status: 'ONLINE' | 'OFFLINE';
}

const STORAGE_KEY = 'gemini_user_api_key';

/**
 * Validates if the key is a real key or just a placeholder
 */
const isValidKeyString = (key: string | undefined): boolean => {
  if (!key) return false;
  const lower = key.toLowerCase();

  // Aggressive placeholder detection
  if (lower.includes('your_gemini_api_key')) return false;
  if (lower.includes('your_api_key')) return false;
  if (lower.includes('replace_me')) return false;
  if (lower.includes('enter_key')) return false;

  // Basic format sanity check
  if (key.length < 20) return false;

  return true;
};

/**
 * Save user provided key to local storage
 */
export const saveUserApiKey = (key: string) => {
  if (isValidKeyString(key)) {
    localStorage.setItem(STORAGE_KEY, key.trim());
  }
};

/**
 * Remove the API key from local storage (used on auth failure)
 */
export const clearUserApiKey = () => {
  localStorage.removeItem(STORAGE_KEY);
};

/**
 * Check if the user has selected an API key via the platform dialog OR entered one manually
 */
export const isGeminiKeySelected = async (): Promise<boolean> => {
  try {
    // 1. Check Local Storage (User entered)
    const storedKey = localStorage.getItem(STORAGE_KEY);
    if (isValidKeyString(storedKey || undefined)) return true;

    // 2. Check AI Studio Environment
    const aistudio = (window as any).aistudio;
    if (aistudio) {
      const hasKey = await aistudio.hasSelectedApiKey();
      if (hasKey) return true;
    }

    // 3. Check Environment Variable (Deployment setting)
    return isValidKeyString(process.env.API_KEY);
  } catch (e) {
    console.error("Failed to check API key status", e);
    return isValidKeyString(process.env.API_KEY);
  }
};

/**
 * Trigger the platform API key selection dialog
 */
export const requestGeminiKey = async (): Promise<void> => {
  const aistudio = (window as any).aistudio;
  if (aistudio) {
    await aistudio.openSelectKey();
  } else {
    console.warn("API Selection dialog is not available in this environment.");
  }
};

/**
 * Direct access to the environment key.
 * Priority: LocalStorage -> Env Var (which is updated by AI Studio)
 */
export const getSecureApiKey = async (): Promise<string> => {
  // 1. Check Local Storage (BYOK)
  const storedKey = localStorage.getItem(STORAGE_KEY);
  if (isValidKeyString(storedKey || undefined)) {
    return storedKey!;
  }

  // 2. Check Environment Variable.
  // We don't perform isValidKeyString check here if we're relying on the environment,
  // as the environment might be providing the key via injection.
  const envKey = process.env.API_KEY;
  if (envKey) {
    return envKey;
  }

  throw new Error("API_KEY_MISSING");
};

export const checkBackendHealth = async (): Promise<SystemHealth> => {
  const keyExists = await isGeminiKeySelected();

  return {
    connected: !!keyExists,
    provider: "Antako Secure Vault",
    latency: `${Math.floor(Math.random() * 30) + 10}ms`,
    status: keyExists ? 'ONLINE' : 'OFFLINE'
  };
};

