// --- Color Palette (Synchronized with UI) ---
const COLORS = {
  primary: [59, 130, 246] as [number, number, number],    // Blue 500
  secondary: [99, 102, 241] as [number, number, number],  // Indigo 500
  slateDark: [15, 23, 42] as [number, number, number],    // Slate 900
  slateMed: [71, 85, 105] as [number, number, number],    // Slate 600
  slateLight: [148, 163, 184] as [number, number, number],// Slate 400
  bgLight: [248, 250, 252] as [number, number, number],   // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],
  success: [16, 185, 129] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
};

/**
 * Utility to convert Blob to Base64 safely in browser
 */
const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

/**
 * Ensures Cyrillic support by loading Montserrat font.
 */
const ensureMontserratFont = async (doc: jsPDF) => {
  try {
    const fontExists = doc.getFontList().hasOwnProperty('Montserrat');
    if (fontExists) {
        doc.setFont('Montserrat');
        return;
    }

    // Montserrat Regular with full character support
    const fontUrl = 'https://cdn.jsdelivr.net/gh/googlefonts/montserrat@master/fonts/ttf/Montserrat-Regular.ttf';
    const response = await fetch(fontUrl);
    if (!response.ok) throw new Error("Font fetch failed");

    const blob = await response.blob();
    const base64 = await blobToBase64(blob);

    doc.addFileToVFS('Montserrat-Regular.ttf', base64);
    doc.addFont('Montserrat-Regular.ttf', 'Montserrat', 'normal');
    doc.setFont('Montserrat');
  } catch (e) {
    console.error("Critical: Font loading failed. Falling back to Helvetica.", e);
    doc.setFont('helvetica');
  }
};

const drawFooter = (doc: jsPDF, pageWidth: number, pageHeight: number, margin: number) => {
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setTextColor(...COLORS.slateLight);
    doc.text("// content audit intelligence by Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });
    doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
  }
};

const drawContainer = (doc: jsPDF, x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
  doc.setFillColor(...color);
  doc.setDrawColor(...COLORS.border);
  doc.roundedRect(x, y, w, h, 2, 2, 'FD');
};

export const generatePdfReport = async (result: AnalysisResult) => {
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  await ensureMontserratFont(doc);

  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 12;
  let cursorY = margin;

  // Header Section
  doc.setFontSize(20);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 6);
  doc.setFontSize(8);
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 6, { align: 'right' });

  cursorY += 12;
  doc.setDrawColor(...COLORS.border);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 6;

  doc.setFontSize(9);
  doc.setTextColor(...COLORS.primary);
  doc.text(`Node: ${result.url}`, margin, cursorY);
  cursorY += 8;

  // Dashboard Scores
  const blockW = (pageWidth - (margin * 2) - 8) / 3;
  const blockH = 20;

  const drawScore = (label: string, score: number, x: number) => {
    drawContainer(doc, x, cursorY, blockW, blockH, COLORS.bgLight);
    doc.setFontSize(6);
    doc.setTextColor(...COLORS.slateMed);
    doc.text(label.toUpperCase(), x + 4, cursorY + 6);
    doc.setFontSize(14);
    const color = score > 80 ? COLORS.success : score > 50 ? COLORS.warning : COLORS.danger;
    doc.setTextColor(...color);
    doc.text(`${score}/100`, x + 4, cursorY + 14);
  };

  drawScore("SEO Health", result.seoScore, margin);
  drawScore("E-E-A-T Quality", result.eeatScore, margin + blockW + 4);
  drawScore("GEO Readiness", result.llmOptimizationScore, margin + (blockW + 4) * 2);

  cursorY += blockH + 8;

  // Analysis Summary
  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['STRATEGIC OVERVIEW']],
    body: [[result.summary]],
    theme: 'plain',
    styles: { font: 'Montserrat', fontSize: 9, textColor: COLORS.slateMed, lineHeight: 1.2, overflow: 'linebreak' },
    headStyles: { font: 'Montserrat', textColor: COLORS.secondary, fontSize: 10, fontStyle: 'bold', cellPadding: { bottom: 2 } },
  });

  cursorY = (doc as any).lastAutoTable.finalY + 8;

  // Strengths & Weaknesses side by side
  const colW = (pageWidth - margin * 2 - 8) / 2;
  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin },
    tableWidth: colW,
    head: [['STRENGTHS']],
    body: result.strengths.map(s => [`• ${s}`]),
    theme: 'plain',
    styles: { font: 'Montserrat', fontSize: 8, cellPadding: 1, textColor: COLORS.slateDark },
    headStyles: { font: 'Montserrat', textColor: COLORS.success, fontStyle: 'bold' }
  });

  (autoTable as any)(doc, {
    startY: cursorY,
    margin: { left: margin + colW + 8 },
    tableWidth: colW,
    head: [['CRITICAL ISSUES']],
    body: result.weaknesses.map(w => [`• ${w}`]),
    theme: 'plain',
    styles: { font: 'Montserrat', fontSize: 8, cellPadding: 1, textColor: COLORS.slateDark },
    headStyles: { font: 'Montserrat', textColor: COLORS.danger, fontStyle: 'bold' }
  });

  // Recommendations
  doc.addPage();
  cursorY = margin;

  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['PRIORITY', 'AREA', 'ACTION', 'IMPLEMENTATION', 'IMPACT']],
    body: result.recommendations.map(r => [
      r.priority.toUpperCase(),
      r.category,
      r.action,
      `${r.description}\n\nFIX:\n${r.fixSteps.map((s,i) => `${i+1}. ${s}`).join('\n')}`,
      r.expectedImpact
    ]),
    theme: 'grid',
    styles: { 
      font: 'Montserrat', 
      fontSize: 7.5, 
      cellPadding: 3, 
      valign: 'top', 
      overflow: 'linebreak', 
      lineColor: COLORS.border, 
      lineWidth: 0.1 
    },
    headStyles: { 
      font: 'Montserrat', 
      fillColor: COLORS.slateDark, 
      textColor: COLORS.white, 
      fontStyle: 'bold', 
      halign: 'center' 
    },
    columnStyles: { 
      0: { cellWidth: 18, halign: 'center', fontStyle: 'bold' }, 
      1: { cellWidth: 18 },
      2: { cellWidth: 35, fontStyle: 'bold', textColor: COLORS.primary },
      4: { cellWidth: 30 }
    },
    didParseCell: (data: any) => {
      if (data.section === 'body' && data.column.index === 0) {
        if (data.cell.raw === 'HIGH') data.cell.styles.textColor = COLORS.danger;
        else if (data.cell.raw === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
      }
    }
  });

  drawFooter(doc, pageWidth, pageHeight, margin);
  doc.save(`audit-report-${Date.now()}.pdf`);
};

